function Modal({title,subtitle,onClose,children}){return <Sheet title={title} onClose={onClose}>{subtitle&&<p className="small muted" style={{marginBottom:20}}>{subtitle}</p>}{children}</Sheet>}
function Form({onSubmit,children,submit='Save changes'}){const [error,setError]=useState(''),[busy,setBusy]=useState(false);return <form onSubmit={async e=>{e.preventDefault();setError('');setBusy(true);try{await onSubmit(Object.fromEntries(new FormData(e.currentTarget)));}catch(e){setError(e.message)}finally{setBusy(false)}}}>{children}{error&&<div className="error" role="alert"><AlertCircle size={17}/>{error}</div>}<footer className="form-footer"><span><LockKeyhole size={13}/> Saved securely in your workspace</span><Button disabled={busy} icon={busy?LoaderCircle:Check}>{busy?'Saving…':submit}</Button></footer></form>}
function Table({columns,rows,empty,onRow}){if(!rows?.length)return <Empty {...empty}/>;return <div className="table-scroll"><table><thead><tr>{columns.map(c=><th key={c.key}>{c.label}</th>)}</tr></thead><tbody>{rows.map((r,i)=><tr key={r.id||i} onClick={onRow?()=>onRow(r):undefined} className={onRow?'clickable':''}>{columns.map(c=><td key={c.key}>{c.render?c.render(r):r[c.key]??'—'}</td>)}</tr>)}</tbody></table></div>}
function Person({name,sub}){return <div className="person"><span className="avatar">{initials(name)}</span><div><strong>{name}</strong><small>{sub}</small></div></div>}

function Auth({onLogin}){const [setup,setSetup]=useState(null),[error,setError]=useState(''),[busy,setBusy]=useState(false),[show,setShow]=useState(false);useEffect(()=>{api('/auth/status').then(d=>setSetup(d.needsSetup)).catch(e=>setError(e.message))},[]);return <div className="auth-shell"><div className="auth-story"><a className="brand" href="/"><span className="brand-mark">f<span>×</span></span>FactX<span className="brand-dot">.</span></a><div className="auth-copy"><div className="eyebrow light"><span/> THE CONNECTED ACADEMIC WORKSPACE</div><h1>Every student.<br/>A clearer<br/><em>way forward.</em></h1><p>Bring your institution’s people, progress, and possibilities into one thoughtful workspace.</p><div className="auth-pill"><ShieldCheck size={17}/> Purpose-built for academic communities</div></div><div className="orb orb-one"/><div className="orb orb-two"/><div className="auth-footer"><span>ACADEMIC MANAGEMENT. HUMAN POTENTIAL.</span><span>FactX © {new Date().getFullYear()}</span></div></div><div className="auth-panel"><div className="auth-top"><ShieldCheck size={16}/> Secure institutional access</div><div className="auth-form"><IconBox icon={setup?Building2:GraduationCap}/><div className="eyebrow">YOUR NEXT CHAPTER STARTS HERE</div><h2>{setup?'Make it your workspace.':'Welcome back.'}</h2><p>{setup?'Set up your institution’s first administrator account. Your workspace starts fresh, with only the data you add.':'Sign in to your academic workspace. Everything you need, all in one place.'}</p>{setup===null?<div className="loading"><LoaderCircle/>Connecting to FactX…</div>:<form onSubmit={async e=>{e.preventDefault();setBusy(true);setError('');try{onLogin(await api('/auth/'+(setup?'setup':'login'),{method:'POST',body:Object.fromEntries(new FormData(e.currentTarget))}));}catch(e){setError(e.message)}finally{setBusy(false)}}}>{setup&&<Field label="Full name"><input name="name" autoComplete="name" placeholder="Your full name" required/></Field>}<Field label="Institutional email"><div className="input-icon"><Mail size={17}/><input name="email" type="email" autoComplete="username" placeholder="you@institution.edu" required/></div></Field><Field label="Password" hint={setup?'Use at least 12 characters.':null}><div className="input-icon"><LockKeyhole size={17}/><input name="password" type={show?'text':'password'} autoComplete={setup?'new-password':'current-password'} placeholder="Enter your password" minLength={setup?12:undefined} required/><button type="button" className="icon-button" aria-label={show?'Hide password':'Show password'} onClick={()=>setShow(!show)}>{show?<EyeOff size={16}/>:<Eye size={16}/>}</button></div></Field>{setup&&<Field label="Setup token" hint="Copy the private first-run token from your server terminal."><input name="token" type="password" placeholder="Paste your setup token" required/></Field>}{error&&<div className="error" role="alert">{error}</div>}<Button disabled={busy} variant="wide" icon={busy?LoaderCircle:ArrowRight}>{busy?'Please wait…':setup?'Create your workspace':'Sign in to FactX'}</Button></form>}<nav className="readiness-links" aria-label="Account help"><a href="/#forgot-password">Forgot password?</a><a href="/#privacy">Privacy</a><a href="/#terms">Terms</a></nav><div className="auth-note"><ShieldCheck size={16}/><span>Your access is tailored to your role.<br/>Contact your administrator for account assistance.</span></div></div><div className="auth-bottom">A little more clarity. A lot more possibility. <span>✳</span></div></div></div>}

